-- 14a — Rede FICTÍCIA da marca "Pódio" (tenant demo) para testar localmente os geradores de eventos simulados (06_, 11_, 14_).
-- Cópia da rede que está em produção em 2026-10-24 (12 produtos, 11 revendedores, 11 endereços, 51 vínculos). Telefones e sites são inventados.
-- Uso local: o tenant `demo` precisa existir (docs/schema-locator-v2.sql cria); o script só insere se ele ainda estiver sem produtos.
do $$ begin
  if exists (select 1 from public.products p join public.tenants t on t.id = p.tenant_id where t.slug = 'demo') then
    raise exception 'o tenant demo local já tem produtos; recrie o banco de teste antes';
  end if;
end $$;

insert into products (tenant_id,sku,name,category,active) select t.id, v.* from tenants t, (values ('WPI-900','Whey Protein Isolado 900g','Proteínas',true),('WPC-900','Whey Protein Concentrado 900g','Proteínas',true),('CRE-300','Creatina Monohidratada 300g','Energia e performance',true),('BCA-120','BCAA 2:1:1 120 cápsulas','Aminoácidos',true),('PRE-300','Pré-Treino Energy 300g','Energia e performance',true),('ALB-500','Albumina 500g','Proteínas',true),('MVA-060','Multivitamínico A-Z 60 cápsulas','Vitaminas',true),('GLU-300','Glutamina 300g','Aminoácidos',true),('OM3-120','Ômega 3 120 cápsulas','Saúde e bem-estar',true),('COL-300','Colágeno Hidrolisado 300g','Saúde e bem-estar',true),('BAR-012','Barra de Proteína (caixa com 12 un)','Proteínas',true),('HIP-3000','Hipercalórico 3kg','Proteínas',true)) as v(sku,name,category,active) where t.slug='demo';

